export default function History() {
  const [sub, setSub] = useState(null);
  const [loading, setLoading] = useState(true);
  const [lessons, setLessons] = useState([]);
  const [introWatched, setIntroWatched] = useState(false);
  const [initialized, setInitialized] = useState(false);

  const navigate = useNavigate();
  const user = JSON.parse(localStorage.getItem("user")) || null;

  // Check if intro was already watched from backend
  useEffect(() => {
    if (!user || !user.id) {
      console.log("User not logged in - skipping video_progress check");
      return;
    }

    console.log("📡 Checking if intro video is already completed for user:", user.id);

    // Fetch video_progress for intro video (lesson_id=0, video_id=0)
    fetch(`http://localhost:8080/video_progress?user_id=${user.id}&lesson_id=1&video_id=1`)
      .then((res) => {
        console.log("Response status:", res.status);
        if (res.ok) {
          return res.json();
        }
        console.warn("Response not OK, status:", res.status);
        return null;
      })
      .then((data) => {
        console.log("📦 Response data:", data);
        if (data && data.completed === true) {
          console.log("✅ Intro video already completed. Setting introWatched to true");
          setIntroWatched(true);
        } else if (data) {
          console.log("⏳ Intro video not completed. completed:", data.completed);
        } else {
          console.log("⏳ No data returned from endpoint");
        }
      })
      .catch((err) => {
        console.warn("⚠️ Could not fetch video_progress:", err.message);
      });
  }, [user]);

  // Only run once on component mount
  useEffect(() => {
    if (initialized) return; // Prevent re-running

    console.log("🔄 useEffect triggered. introWatched:", introWatched);

    // Skip fetching resources - use fallback
    const found = null; // No resource found
    setSub(found);

    // Create lessons from HISTORY_LESSONS data
    const pad = HISTORY_LESSONS.map((lesson) => ({
      id: `local-${lesson.lesson_number}`,
      lesson_number: lesson.lesson_number,
      title: lesson.title,
      status: lesson.lesson_number === 1 ? "unlocked" : "locked",
      videos: lesson.videos
    }));

    console.log("📚 Lessons created:", pad);
    setLessons(pad);
    setLoading(false);
    setInitialized(true); // Mark as initialized to prevent re-runs
  }, []); // Empty dependency array - only run once on mount

  function markIntroWatched() {
    console.log("🔘 Button clicked - markIntroWatched() called");

    // Send to backend if user is logged in
    if (user && user.id) {
      const videoProgressData = {
        user_id: user.id,
        lesson_id: 1,  // Special ID for intro video (not part of any lesson)
        video_id: 1,   // Special ID for intro video
        watched: true,
        completed: true,
        watch_started_at: new Date().toISOString(),
        completed_at: new Date().toISOString(),
      };

      console.log("📡 Sending to backend /video_progress:", videoProgressData);

      fetch("http://localhost:8080/video_progress", {
        method: "POST",
        headers: { 
          "Content-Type": "application/json",
          "Accept": "application/json"
        },
        body: JSON.stringify(videoProgressData),
      })
        .then((res) => {
          console.log("✅ Response status:", res.status);

          if (res.status === 201 || res.status === 200) {
            return res.json().then(data => {
              console.log("✓ Video progress saved successfully:", data);
              return data;
            }).catch(() => {
              console.log("✓ Saved (no JSON body)");
              return null;
            });
          } else if (res.status === 404) {
            console.error("❌ Endpoint not found (404)");
          } else if (res.status === 500) {
            console.error("❌ Server error (500)");
          }
        })
        .catch((err) => {
          console.error("❌ Network error:", err.message);
        });
    } else {
      console.warn("⚠️ User not logged in - cannot save video progress");
    }

    // Set intro watched state
    setIntroWatched(true);
  }

  function markLessonCompleted(lessonId) {
    setLessons((prev) => {
      const updated = prev.map((ls) => {
        if (ls.id === lessonId) {
          return { ...ls, status: "completed" };
        }
        return ls;
      });

      // Unlock next lesson if the current one is completed
      const completedLessonIndex = updated.findIndex((l) => l.id === lessonId);
      if (completedLessonIndex >= 0 && completedLessonIndex < updated.length - 1) {
        const nextLesson = updated[completedLessonIndex + 1];
        if (nextLesson.status === "locked") {
          updated[completedLessonIndex + 1] = { ...nextLesson, status: "unlocked" };
        }
      }

      return updated;
    });

    // Persist to backend if not a local lesson
    if (!String(lessonId).startsWith("local-")) {
      fetch(`http://localhost:8080/lesson_progress/complete`, {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ user_id: user?.id, lesson_id: lessonId }),
      }).catch((e) => console.warn("Could not persist completion:", e));
    }
  }

  function viewLesson(lesson) {
    console.log("🔘 View Lesson button clicked. Lesson:", lesson);
    console.log("🔗 Navigating to /lesson/" + lesson.id);
    navigate(`/lesson/${lesson.id}`, { state: { lesson, lessons, subId: sub?.id } });
  }

  return (
    <div className="dashboard-page" style={{ width: "100%" }}>
      <Sidebar />
      <main className="dashboard-main" style={{ padding: "2rem", margin: "0", width: "100%", maxWidth: "100%", flex: "1 1 auto" }}>
        <header className="dashboard-header" style={{ paddingLeft: "0", paddingRight: "0", marginBottom: "2rem", display: "block" }}>
          <h1 style={{ color: "#f5f7ff", margin: "0 0 0.5rem 0" }}>History</h1>
          <p className="dashboard-subtitle" style={{ margin: "0" }}>Explore the events and people that shaped our world.</p>
        </header>

        {loading ? (
          <p className="dashboard-loading">Loading...</p>
        ) : (
          <div style={{ display: "grid", gridTemplateColumns: "1fr 1fr", gap: "1.5rem", width: "100%", margin: "0" }}>
            {/* Intro video - Left side */}
            <section style={{ 
              background: "radial-gradient(circle at top, #111827, #020617)",
              border: "1px solid rgba(148, 163, 184, 0.2)",
              borderRadius: "16px",
              padding: "2rem",
              boxShadow: "0 8px 24px rgba(0, 0, 0, 0.3)",
              height: "fit-content",
              position: "sticky",
              top: "2rem"
            }}>
              <h2 style={{ fontSize: "1.4rem", margin: "0 0 1.5rem 0", color: "#f5f7ff", fontWeight: "700" }}>Intro to History</h2>
              <div style={{ position: "relative", paddingBottom: "56.25%", height: 0, marginBottom: "1.5rem", borderRadius: "12px", overflow: "hidden", border: "1px solid rgba(148, 163, 184, 0.2)" }}>
                <iframe
                  title="History Intro"
                  src="https://www.youtube.com/embed/ZxFzDJg1l2s?rel=0"
                  style={{ position: "absolute", top: 0, left: 0, width: "100%", height: "100%" }}
                  frameBorder="0"
                  allowFullScreen
                />
              </div>
              {!introWatched ? (
                <button 
                  onClick={markIntroWatched}
                  style={{
                    width: "100%",
                    background: "linear-gradient(135deg, #6c5ce7, #00cec9)",
                    color: "white",
                    border: "none",
                    padding: "0.85rem 1.5rem",
                    borderRadius: "8px",
                    fontSize: "0.95rem",
                    fontWeight: "600",
                    cursor: "pointer",
                    transition: "all 300ms cubic-bezier(0.34, 1.56, 0.64, 1)",
                    boxShadow: "0 10px 25px rgba(108, 92, 231, 0.3)"
                  }}
                  onMouseEnter={(e) => e.target.style.transform = "translateY(-2px)"}
                  onMouseLeave={(e) => e.target.style.transform = "translateY(0)"}
                >
                  I've finished watching
                </button>
              ) : (
                <div style={{
                  padding: "0.85rem 1rem",
                  background: "rgba(16, 185, 129, 0.15)",
                  color: "#10b981",
                  borderRadius: "8px",
                  fontWeight: "600",
                  textAlign: "center",
                  fontSize: "0.95rem",
                  border: "1px solid rgba(16, 185, 129, 0.25)"
                }}>
                  ✓ Intro Completed
                </div>
              )}
            </section>

            {/* Lessons - Right side */}
            <section>
              <div>
                <div style={{ display: "flex", alignItems: "center", justifyContent: "space-between", gap: "1rem", marginBottom: "1.5rem" }}>
                  <h2 style={{ fontSize: "1.4rem", margin: 0, color: "#f5f7ff", fontWeight: "700" }}>Lessons</h2>
                  <p style={{ fontSize: "0.85rem", color: "#9ca3af", margin: 0, whiteSpace: "nowrap", background: "rgba(108, 92, 231, 0.15)", padding: "0.5rem 1rem", borderRadius: "8px" }}>
                    {lessons.filter(l => l.status === "completed").length} / {lessons.length} completed
                  </p>
                </div>
                <ul className="lessons-grid">
                  {lessons.map((lesson) => (
                    <li key={lesson.id} className={`lesson-card ${lesson.status}`}>
                      <div className="lesson-card-number">{lesson.lesson_number}</div>
                      <div className="lesson-card-content">
                        <h3>{lesson.title}</h3>
                        <p className="lesson-status">
                          {lesson.status === "completed" && "✓ Completed"}
                          {lesson.status === "unlocked" && "Ready to start"}
                          {lesson.status === "locked" && "Locked"}
                          {lesson.status === "schedule_locked" && "Select resources"}
                        </p>
                      </div>
                      <button
                        className="lesson-card-btn"
                        disabled={lesson.status === "locked" || lesson.status === "schedule_locked"}
                        onClick={() => viewLesson(lesson)}
                      >
                        View →
                      </button>
                    </li>
                  ))}
                </ul>
              </div>
            </section>
          </div>
        )}
      </main>
    </div>
  );
}
